const row = $input.first().json;
let nav = {};
try { nav = $('Nav laden').first().json; } catch (e) { nav = {}; }

function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function fmtDate(v) {
  if (!v) return '-';
  return new Date(v).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}
const RICHTUNG_LABEL = { kauf: 'LONG', verkauf: 'SHORT' };

const CSS = 'body{font-family:sans-serif;background:#0f1115;color:#e6e6e6;margin:0;padding:32px;max-width:1000px;margin:0 auto;}'
  + 'h1{font-size:22px;color:#fff;margin-bottom:4px;} h2{font-size:15px;color:#fff;margin-top:0;margin-bottom:8px;display:flex;align-items:center;gap:8px;}'
  + '.meta{color:#9aa0a6;font-size:13px;margin-bottom:20px;} .hint{color:#9aa0a6;font-size:12px;}'
  + '.section{background:#181b21;border:1px solid #2a2d34;border-radius:8px;padding:16px 20px;margin-bottom:14px;}'
  + '.section a.mehr{color:#8ab4f8;text-decoration:none;font-size:12px;margin-left:auto;}'
  + '.row{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #22242a;font-size:13px;}'
  + '.row:last-child{border-bottom:none;} .row a{color:#e6e6e6;text-decoration:none;} .row a:hover{color:#8ab4f8;}'
  + '.count{display:inline-block;background:#5b8def;color:#0f1115;font-weight:700;border-radius:999px;padding:1px 9px;font-size:12px;}'
  + '.count.zero{background:#22242a;color:#7a7d84;}'
  + '.section-empty{color:#7a7d84;font-size:12px;font-style:italic;}'
  + '.badge{display:inline-block;padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600;background:#3a2c1c;color:#e0a854;}';

const NAVBAR_LINKS = '<div style="background:#232323;border:1px solid #444;border-radius:6px;padding:8px 14px;margin-bottom:20px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;"><a href="/webhook/aktien-status" style="color:#8ab4f8;text-decoration:none;">Status</a></div>';

function pageWrap(title, body) {
  return '<!DOCTYPE html><html lang="de"><head><meta charset="utf-8"><title>' + esc(title) + '</title><style>' + CSS + '</style></head><body>'
    + (nav && nav.navHtml ? nav.navHtml : NAVBAR_LINKS)
    + body
    + '</body></html>';
}

function section(titel, anzahl, link, linkLabel, items, renderer, emptyText) {
  const countKlass = anzahl > 0 ? 'count' : 'count zero';
  return '<div class="section">'
    + '<h2>' + esc(titel) + ' <span class="' + countKlass + '">' + anzahl + '</span>'
    + '<a class="mehr" href="' + link + '">' + esc(linkLabel) + ' &rarr;</a></h2>'
    + (!items || items.length === 0
      ? '<div class="section-empty">' + esc(emptyText) + '</div>'
      : items.map(renderer).join(''));
}

const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });

const tradeEntscheidungenHtml = section(
  'Offene Trade-Entscheidungen', row.trade_entscheidungen_anzahl || 0, '/webhook/heute-handeln', 'Zu Heute Handeln',
  row.trade_entscheidungen, r =>
    '<div class="row"><a href="/webhook/heute-handeln?id=' + esc(r.id) + '">' + esc(r.ticker) + ' - ' + (RICHTUNG_LABEL[r.richtung] || esc(r.richtung)) + '</a><span class="hint">Score: ' + esc(r.opportunity_score ?? '-') + '</span></div>',
  'Keine offenen Trade-Ideen.'
);

const tradeReviewsHtml = section(
  'Offene Trade-Reviews', row.trade_reviews_anzahl || 0, '/webhook/trade-review', 'Zu Paper-Trading-Review',
  row.trade_reviews, t =>
    '<div class="row"><a href="/webhook/trade-review?id=' + esc(t.trade_id) + '">' + esc(t.ticker) + '</a><span class="hint">PnL: ' + esc(t.net_pnl ?? '-') + ' &middot; ' + fmtDate(t.exit_time) + '</span></div>',
  'Keine offenen Reviews.'
);

const newsReviewsHtml = section(
  'Offene News-Reviews', row.news_reviews_anzahl || 0, '/webhook/news-pruefen', 'Zu News Prüfen',
  null, null,
  (row.news_reviews_anzahl || 0) > 0 ? '' : 'Keine offenen News-Bewertungen.'
);

const falseNegativesHtml = section(
  'Gemeldete mögliche False Negatives', row.false_negatives_anzahl || 0, '/webhook/news-pruefen', 'Zu News Prüfen',
  row.false_negatives, f =>
    '<div class="row"><a href="/webhook/news-pruefen?id=' + esc(f.news_id) + '">' + esc(f.title) + '</a><span class="badge">' + esc(f.status) + '</span></div>',
  'Keine offenen Meldungen.'
);

const lernvorschlaegeHtml = section(
  'Offene Lernvorschläge', row.lernvorschlaege_anzahl || 0, '/webhook/lernvorschlaege', 'Zu Lernvorschläge',
  row.lernvorschlaege, l =>
    '<div class="row"><span>' + esc(l.target_type) + ': ' + esc(l.target_value) + '</span><span class="hint">Fallzahl: ' + esc(l.sample_size) + ' &middot; Konfidenz: ' + esc(l.confidence_level || '-') + '</span></div>',
  'Keine offenen Lernvorschläge.'
);

const html = pageWrap('Lernen & Feedback', ''
  + '<h1>Lernen &amp; Feedback</h1>'
  + '<div class="meta">Stand: ' + now + ' &middot; Aggregations-Übersicht offener Entscheidungen über alle Bereiche - rein lesend, keine Aktion ändert hier direkt etwas.</div>'
  + tradeEntscheidungenHtml + tradeReviewsHtml + newsReviewsHtml + falseNegativesHtml + lernvorschlaegeHtml
  + '<div class="hint">Einzelnes Feedback wird nie automatisch zu einer Regeländerung. Erst Aggregation über mehrere Fälle, dann ein Lernvorschlag, dann Simulation/OOS, dann manuelle Freigabe - siehe HUMAN_IN_THE_LOOP_ARCHITECTURE.md Abschnitt 6.</div>'
);

return [{ json: { html } }];
